function ticketSuffix(s) {
  let seen = new Set();
  let result = '';
  for (let i = s.length - 1; i >= 0; i--) {
    if (seen.has(s[i])) break;
    seen.add(s[i]);
    result = s[i] + result;
  }
  return result;
}
