function crateFields(s) {
  let result = [];
  let current = '';
  let inQuote = false;
  for (let i = 0; i < s.length; i++) {
    let c = s[i];
    if (c === '"' && !inQuote) {
      inQuote = true;
    } else if (c === '"' && inQuote) {
      if (i + 1 < s.length && s[i + 1] === '"') {
        current += '"';
        i++;
      } else {
        inQuote = false;
      }
    } else if (c === ';' && !inQuote) {
      result.push(current);
      current = '';
    } else {
      current += c;
    }
  }
  if (inQuote) return null;
  result.push(current);
  return result;
}
