function paintWindows(intervals) {
  const merged = [];
  for (const [start, end, label] of intervals) {
    let i = 0;
    while (i < merged.length && merged[i][1] < start) i++;
    while (i < merged.length && merged[i][0] <= end) {
      if (merged[i][2] === label) {
        merged[i][1] = Math.max(merged[i][1], end);
        break;
      }
      i++;
    }
    if (i === merged.length || merged[i][0] > end) {
      merged.splice(i, 0, [start, end, label]);
    }
  }
  return merged;
}
