function routePieces(path) {
  const parts = path.split('/').filter(p => p !== '' && p !== '.');
  const result = [];
  for (let i = 0; i < parts.length; i++) {
    if (parts[i] === '..') {
      if (result.length > 0 && !result[result.length - 1].startsWith('!')) {
        result.pop();
      }
    } else {
      result.push(parts[i]);
    }
  }
  return result.length ? '/' + result.join('/') : '/';
}
