function ribbonExpand(s) {
  let i = 0;
  function parse() {
    let res = '';
    while (i < s.length) {
      if (s[i] === ']') {
        i++;
        return res;
      }
      if (s[i] === '[') {
        i++;
        let count = '';
        while (i < s.length && s[i] >= '0' && s[i] <= '9') count += s[i++];
        if (count === '' || s[i] !== ']') return null;
        i++;
        const sub = parse();
        if (sub === null) return null;
        res += sub.repeat(parseInt(count, 10));
      } else if (s[i] >= 'a' && s[i] <= 'z') {
        res += s[i++];
      } else {
        return null;
      }
    }
    return res;
  }
  const result = parse();
  return result !== null && result.length <= 1000 ? result : null;
}
