function lPadChunks(s, width) {
  if (s === "") return [];
  const chunks = [];
  for (let i = 0; i < s.length; i += width) {
    let chunk = s.slice(i, i + width);
    if (chunk.length < width) chunk += ".".repeat(width - chunk.length);
    chunks.push(chunk);
  }
  return chunks;
}
