function lOddMultiplicity(arr) {
  const count = {};
  const result = [];
  for (let num of arr) {
    count[num] = (count[num] || 0) + 1;
  }
  for (let key in count) {
    if (count[key] % 2 === 1) {
      result.push(parseInt(key));
    }
  }
  return result.sort((a, b) => a - b);
}
