function lTransposeRagged(arr) {
  if (arr.length === 0 || arr.every(r => r.length === 0)) return [];
  const maxLen = Math.max(...arr.map(r => r.length));
  return Array.from({ length: maxLen }, (_, i) =>
    arr.map(r => (i < r.length ? r[i] : null))
  );
}
