function lUndoBag(operations) {
  const bag = [];
  const history = [];

  for (const [kind, value] of operations) {
    if (kind === 'add') {
      bag.push(value);
      history.push(['add', value]);
    } else if (kind === 'remove') {
      const index = bag.lastIndexOf(value);
      if (index !== -1) {
        bag.splice(index, 1);
        history.push(['remove', value]);
      }
    } else if (kind === 'undo') {
      if (history.length > 0) {
        const [op, val] = history.pop();
        if (op === 'add') {
          const index = bag.indexOf(val);
          if (index !== -1) bag.splice(index, 1);
        } else if (op === 'remove') {
          bag.push(val);
        }
      }
    }
  }

  return bag;
}
