function lCycleAnchor(next, start) {
    let slow = start, fast = start;
    while (true) {
        slow = next[slow];
        fast = next[next[fast]];
        if (slow === fast) break;
    }
    let cycleLength = 0;
    let temp = slow;
    do {
        temp = next[temp];
        cycleLength++;
    } while (temp !== slow);
    let count = 0;
    let entry = start;
    while (entry !== slow) {
        entry = next[entry];
        count++;
    }
    let minIndex = slow;
    temp = next[slow];
    while (temp !== slow) {
        if (temp < minIndex) minIndex = temp;
        temp = next[temp];
    }
    return [count, cycleLength, minIndex];
}
