function lBackspaceRuns(s) {
  const stack = [];
  for (const c of s) {
    if (c === '#') {
      if (stack.length > 0) stack.pop();
    } else {
      stack.push(c);
    }
  }
  const result = [];
  let count = 1;
  for (let i = 1; i < stack.length; i++) {
    if (stack[i] === stack[i - 1]) count++;
    else {
      result.push(count);
      count = 1;
    }
  }
  if (count > 0) result.push(count);
  return result;
}
