function lIntervalParity(intervals) {
  const events = [];
  for (const [s, e] of intervals) {
    events.push([s, 1], [e, -1]);
  }
  events.sort((a, b) => a[0] - b[0] || a[1] - b[1]);

  const result = [];
  let count = 0, start = null;
  for (const [pos, delta] of events) {
    if (count % 2 === 1 && start !== null) result.push([start, pos]);
    count += delta;
    if (count % 2 === 1) start = pos;
  }
  return result;
}
